// A synchronous loop blocks the single JS thread, even for timers.
const start = Date.now();
setTimeout(() => {
  const late = Date.now() - start;
  // The timer wanted 0 ms but had to wait for the loop below to finish.
  console.log("timer ran after >= 50 ms:", late >= 50);
}, 0);
