// Virtual-time model of libuv's thread pool: 4 workers, FIFO queue.
function simulate(poolSize, jobs) {
  const free = new Array(poolSize).fill(0); // time each worker becomes free
  const done = {};
  for (const j of jobs.sort((a, b) => a.arrive - b.arrive)) {
    free.sort((a, b) => a - b);
    const begin = Math.max(free[0], j.arrive); // wait for a free worker
    free[0] = begin + j.cost;
    done[j.name] = free[0] - j.arrive; // latency seen by the caller
  }
  return done;
}
