const { Writable } = require("stream");
let received = 0;
// Slow consumer: finishes each chunk on a later turn of the loop.
const slow = new Writable({
  highWaterMark: 16, // bytes
  write(chunk, enc, cb) { received++; setImmediate(cb); },
});
let sent = 0, paused = 0;
function produce() {
  while (sent < 20) {
    sent++;
    // write() returns false once the internal buffer reaches highWaterMark
    if (!slow.write(Buffer.alloc(8))) {
      paused++;
      console.log("buffer full after chunk", sent, "- waiting for drain");
      slow.once("drain", produce); // resume only when the consumer caught up
      return;
    }
  }
  slow.end();
}
slow.on("finish", () => console.log("sent", sent, "received", received, "pauses", paused));
produce();

