class Emitter {
  constructor() { this.map = new Map(); }
  on(name, fn) {
    if (!this.map.has(name)) this.map.set(name, []);
    this.map.get(name).push(fn);
    return this;
  }
  once(name, fn) {
    const wrapper = (...args) => { this.off(name, wrapper); fn.apply(this, args); };
    wrapper.listener = fn; // lets off(fn) find the wrapper
    return this.on(name, wrapper);
  }
  off(name, fn) {
    const list = this.map.get(name) || [];
    for (let i = list.length - 1; i >= 0; i--) { // newest match first
      if (list[i] === fn || list[i].listener === fn) { list.splice(i, 1); break; }
    }
    return this;
  }
  emit(name, ...args) {
    const list = this.map.get(name);
    if (!list || list.length === 0) {
      if (name === "error") throw args[0] instanceof Error ? args[0] : new Error("Unhandled error");
      return false;
    }
    for (const fn of [...list]) fn.apply(this, args); // copy: safe if listeners change
    return true;
  }
}
