const { Worker, isMainThread, workerData, parentPort } = require("worker_threads");
if (isMainThread) {
  const N = 1000;
  // SharedArrayBuffer is shared, not copied, between threads.
  const shared = new Int32Array(new SharedArrayBuffer(4));
  const parts = [[1, 500], [501, 1000]];
  let finished = 0;
  const sums = [];
  console.log("main: summing 1.." + N + " with 2 workers");
  for (const [from, to] of parts) {
    const w = new Worker(__filename, { workerData: { from, to, shared } });
    w.on("message", (m) => sums.push(m));
    w.on("exit", () => {
      if (++finished === parts.length) {
        console.log("partial sums:", sums.sort((a, b) => a - b).join(", "));
        console.log("shared total:", shared[0]);
      }
    });
  }
} else {
  const { from, to, shared } = workerData;
  let sum = 0;
  for (let i = from; i <= to; i++) sum += i; // CPU work off the main thread
  Atomics.add(shared, 0, sum); // safe concurrent update of shared memory
  parentPort.postMessage(sum);
}

// A tiny model of CommonJS: cache the module BEFORE running it.
const sources = {
  a: function (module, exports, require) {
    exports.early = "a-early";
    const b = require("b");
    console.log("a sees b.done =", b.done);
    exports.late = "a-late";
  },
  b: function (module, exports, require) {
    const a = require("a"); // cycle: a is only partly finished
    console.log("b sees a.early =", a.early, "| a.late =", a.late);
    exports.done = true;
  },
};
const cache = {};
function myRequire(name) {
  if (cache[name]) return cache[name].exports; // second request: cached, maybe partial
  const module = { exports: {} };
  cache[name] = module; // cached before executing
  sources[name](module, module.exports, myRequire);
  return module.exports;
}
myRequire("a");
console.log("final a:", JSON.stringify(cache.a.exports));

