// Classic leak: an unbounded Map used as a cache, never evicted.
const leaky = new Map();
function handleLeaky(id) { leaky.set("req-" + id, Buffer.alloc(1024)); }

// Fix: bound the cache size (simple LRU using Map insertion order).
const MAX = 100;
const bounded = new Map();
function handleBounded(id) {
  bounded.set("req-" + id, Buffer.alloc(1024));
  if (bounded.size > MAX) bounded.delete(bounded.keys().next().value); // evict oldest
}
for (let id = 1; id <= 5000; id++) { handleLeaky(id); handleBounded(id); }
console.log("requests served: 5000");
console.log("leaky cache entries:", leaky.size, "~", (leaky.size / 1024).toFixed(1), "MB retained");
